import { createHash } from "node:crypto";
import manifest from "@/lib/sat/cfdi40/manifest.json";
import { Cfdi40Error, cfdi40Issue, type Cfdi40IssueCode } from "./errors";

// Fase 5C.8: the official Timbre Fiscal Digital 1.1 resources (TimbreFiscalDigitalv11.xsd and
// cadenaoriginal_TFD_1_1.xslt) from src/lib/sat/cfdi40/tfd11.json, generated byte-exact from
// resources/sat/cfdi40 by scripts/sat/tfd11-bundle.mjs. A JSON module bundled with the server
// code: no runtime file read and no download. Every text is re-hashed against the manifest;
// the XSD must declare the TFD namespace and import only what the manifest declares, and the
// XSLT must include nothing. Anything else fails closed.

export const tfdNamespace = "http://www.sat.gob.mx/TimbreFiscalDigital";
export const tfd11XsdUrl =
  "http://www.sat.gob.mx/sitio_internet/cfd/TimbreFiscalDigital/TimbreFiscalDigitalv11.xsd";
export const tfd11XsltUrl =
  "http://www.sat.gob.mx/sitio_internet/cfd/TimbreFiscalDigital/cadenaoriginal_TFD_1_1.xslt";
/** The standard xsi:schemaLocation of a TFD 1.1 node. */
export const tfd11SchemaLocation = `${tfdNamespace} ${tfd11XsdUrl}`;

export type Tfd11Bundle = {
  readonly xsd: {
    readonly url: string;
    readonly name: string;
    readonly namespace: string;
    readonly imports: readonly string[];
    readonly sha256: string;
    readonly bytes: Uint8Array;
  };
  readonly xslt: {
    readonly url: string;
    readonly name: string;
    readonly sha256: string;
    /** Exact UTF-8 text of the official stylesheet. */
    readonly text: string;
  };
};
export type Tfd11BundleSource = {
  xsd: {
    url: string;
    name: string;
    namespace: string;
    imports: readonly string[];
    sha256: string;
    text: string;
  };
  xslt: { url: string; name: string; sha256: string; text: string };
};
type ManifestResource = {
  name: string;
  kind: string;
  url: string;
  sha256: string;
  namespace?: string;
  imports?: readonly string[];
};

const integrity = (code: Cfdi40IssueCode, name: string) =>
  new Cfdi40Error([cfdi40Issue(code, "TFD/" + name, "ORBIT")]);
const sha256 = (data: Uint8Array) =>
  createHash("sha256").update(data).digest("hex");
const sameList = (a: readonly string[], b: readonly string[]) =>
  a.length === b.length && a.every((value, i) => value === b[i]);

/**
 * Checks a TFD bundle against the manifest. Throws CFDI_XSD_SCHEMA_UNAVAILABLE /
 * CFDI_XSD_SCHEMA_INTEGRITY_FAILED (XSD) or SAT_XSLT_RESOURCE_MISSING /
 * SAT_XSLT_RESOURCE_INTEGRITY_FAILED (XSLT).
 */
export function verifyTfd11Bundle(
  source: Tfd11BundleSource,
  resources: readonly ManifestResource[] = manifest.resources as ManifestResource[],
): Tfd11Bundle {
  const xsdEntry = resources.find(
    (r) => r.kind === "TFD_XSD" && r.url === tfd11XsdUrl,
  );
  const xsltEntry = resources.find(
    (r) => r.kind === "TFD_XSLT" && r.url === tfd11XsltUrl,
  );
  if (!xsdEntry || source?.xsd?.url !== tfd11XsdUrl)
    throw integrity(
      "CFDI_XSD_SCHEMA_UNAVAILABLE",
      "TimbreFiscalDigitalv11.xsd",
    );
  if (!xsltEntry || source?.xslt?.url !== tfd11XsltUrl)
    throw integrity("SAT_XSLT_RESOURCE_MISSING", "cadenaoriginal_TFD_1_1.xslt");
  const bytes = new Uint8Array(Buffer.from(source.xsd.text, "utf8"));
  const imports = [
    ...source.xsd.text.matchAll(
      /<xs:(?:import|include|redefine|override)\b[^>]*?\bschemaLocation="([^"]+)"/g,
    ),
  ].map((m) => m[1]);
  const declaredNamespace =
    /<xs:schema\b[^>]*?\btargetNamespace="([^"]+)"/.exec(source.xsd.text)?.[1];
  if (
    source.xsd.sha256 !== xsdEntry.sha256 ||
    sha256(bytes) !== xsdEntry.sha256 ||
    xsdEntry.namespace !== tfdNamespace ||
    source.xsd.namespace !== tfdNamespace ||
    declaredNamespace !== tfdNamespace ||
    !sameList(imports, xsdEntry.imports ?? []) ||
    !sameList(source.xsd.imports, imports)
  )
    throw integrity(
      "CFDI_XSD_SCHEMA_INTEGRITY_FAILED",
      "TimbreFiscalDigitalv11.xsd",
    );
  const xsltBytes = new Uint8Array(Buffer.from(source.xslt.text, "utf8"));
  if (
    source.xslt.sha256 !== xsltEntry.sha256 ||
    sha256(xsltBytes) !== xsltEntry.sha256 ||
    /<xsl:(?:include|import)\b/.test(source.xslt.text)
  )
    throw integrity(
      "SAT_XSLT_RESOURCE_INTEGRITY_FAILED",
      "cadenaoriginal_TFD_1_1.xslt",
    );
  return Object.freeze({
    xsd: Object.freeze({
      url: tfd11XsdUrl,
      name: xsdEntry.name,
      namespace: tfdNamespace,
      imports: Object.freeze([...imports]),
      sha256: xsdEntry.sha256,
      bytes,
    }),
    xslt: Object.freeze({
      url: tfd11XsltUrl,
      name: xsltEntry.name,
      sha256: xsltEntry.sha256,
      text: source.xslt.text,
    }),
  });
}

let loaded: Promise<Tfd11Bundle> | undefined;
/** The verified official TFD 1.1 resources, loaded once. */
export function loadTfd11Bundle() {
  return (loaded ??= import("@/lib/sat/cfdi40/tfd11.json").then((module) =>
    verifyTfd11Bundle(module.default),
  ));
}
